package bottlesong

import "strings"

var numberWords = map[int]string{
	0:  "no",
	1:  "one",
	2:  "two",
	3:  "three",
	4:  "four",
	5:  "five",
	6:  "six",
	7:  "seven",
	8:  "eight",
	9:  "nine",
	10: "ten",
}

// bottlePhrase returns the phrase for a count of bottles, e.g. "ten green bottles"
// or "one green bottle" (singular for a count of 1).
func bottlePhrase(count int) string {
	noun := "bottles"
	if count == 1 {
		noun = "bottle"
	}
	return numberWords[count] + " green " + noun
}

// verse returns the four lines of the verse starting with the given number of bottles.
func verse(bottles int) []string {
	first := strings.Title(bottlePhrase(bottles)) + " hanging on the wall,"
	return []string{
		first,
		first,
		"And if one green bottle should accidentally fall,",
		"There'll be " + bottlePhrase(bottles-1) + " hanging on the wall.",
	}
}

// Recite returns the lyrics for the verses of the song, starting with
// startBottles bottles and reciting takeDown verses. Verses are separated
// by a blank line.
func Recite(startBottles, takeDown int) []string {
	var lines []string
	for n := startBottles; n > startBottles-takeDown; n-- {
		if len(lines) > 0 {
			lines = append(lines, "")
		}
		lines = append(lines, verse(n)...)
	}
	return lines
}

